import{_ as a,o,c as t,ag as r}from"./chunks/framework.Pp2klvcf.js";const m=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/polyrepo/troubleshooting.md","filePath":"zh/polyrepo/troubleshooting.md","lastUpdated":1788681727000}'),l={name:"zh/polyrepo/troubleshooting.md"};function d(n,e,i,c,h,s){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="页面显示-cannot-get" tabindex="-1">页面显示 Cannot GET / <a class="header-anchor" href="#页面显示-cannot-get" aria-label="Permalink to &quot;页面显示 Cannot GET /&quot;">​</a></h2><p>先核对终端中的实际地址。3000 是常用服务端口，可能被其他本地服务占用；默认应用现使用 <code>127.0.0.1:5173</code> 并启用 strictPort。端口占用时修改 <code>.env.local</code> 的 VITE_PORT 或停止你确认不用的服务，不要盲目结束未知进程。</p><h2 id="单模式正常-all-模式样式不一致" tabindex="-1">单模式正常，all 模式样式不一致 <a class="header-anchor" href="#单模式正常-all-模式样式不一致" aria-label="Permalink to &quot;单模式正常，all 模式样式不一致&quot;">​</a></h2><p>检查是否引入多个全局 reset，页面是否借用了某组件库的变量，以及当前框架是否有对应 Provider。应用样式使用 <code>--fv-*</code>，避免通用类名污染。不要简单堆叠 <code>!important</code> 掩盖来源。</p><h2 id="暗色背景正常-组件仍然是浅色" tabindex="-1">暗色背景正常，组件仍然是浅色 <a class="header-anchor" href="#暗色背景正常-组件仍然是浅色" aria-label="Permalink to &quot;暗色背景正常，组件仍然是浅色&quot;">​</a></h2><p>确认 App.vue 的 @ui-theme 生效，以及主题服务读取的是统一 Store。CSS-in-JS 框架需要 Provider，切换 html class 本身不够。</p><h2 id="切换分支或-mode-后出现预构建错误" tabindex="-1">切换分支或 mode 后出现预构建错误 <a class="header-anchor" href="#切换分支或-mode-后出现预构建错误" aria-label="Permalink to &quot;切换分支或 mode 后出现预构建错误&quot;">​</a></h2><p>停止旧开发进程，按当前 lockfile 安装依赖，再执行 <code>pnpm dev --force</code> 重建 Vite 依赖缓存。不要把 main 的 node_modules 当成 polyrepo 的依赖使用。</p><h2 id="登录失败仍跳页-接口返回-html" tabindex="-1">登录失败仍跳页 / 接口返回 HTML <a class="header-anchor" href="#登录失败仍跳页-接口返回-html" aria-label="Permalink to &quot;登录失败仍跳页 / 接口返回 HTML&quot;">​</a></h2><p>检查是否接到了正确服务和 API 前缀。响应必须符合业务协议；生产预览不包含开发 Mock。开发接口固定为 <code>/api/user/*</code>。</p>',11)])])}const u=a(l,[["render",d]]);export{m as __pageData,u as default};
